// CBSE 12 Mathematics ch02 Inverse Trigonometric Functions — practice bank with independent re-solve
// checks: every principal value, domain, range and composition is recomputed with Math.asin / acos /
// atan (and the branch definitions of cosec⁻¹, sec⁻¹, cot⁻¹ below) and compared with the key, the
// options' values (typed separately from the option text), or the exact form in the model answer.
// Elementary properties of inverse trigonometric functions are deleted from the 2026-27 syllabus and
// are never used: every value is found from the definition of the principal value branch.
import { Q, caseQ, child, mk, r, plot, gcd } from '../../cbse-12-mathematics-ch01/src/lib.mjs';

export const P = Math.PI;
const S2 = Math.SQRT2, S3 = Math.sqrt(3);
/** Principal branches computed from their definitions (value in the range whose trig ratio is x). */
export const acsc = (x) => (Math.abs(x) < 1 ? NaN : Math.asin(1 / x)); // in [-π/2, π/2] \ {0}, sin y = 1/x
export const asec = (x) => (Math.abs(x) < 1 ? NaN : Math.acos(1 / x)); // in [0, π] \ {π/2}, cos y = 1/x
export const acot = (x) => (x === 0 ? P / 2 : x > 0 ? Math.atan(1 / x) : P + Math.atan(1 / x)); // in (0, π)
/** Exact LaTeX of a rational multiple of π, e.g. 2π/3 → \dfrac{2\pi}{3}; null if not a simple multiple. */
export function piTex(v) {
  const q = v / P;
  for (const d of [1, 2, 3, 4, 5, 6, 8, 10, 12]) {
    const n = Math.round(q * d);
    if (Math.abs(q * d - n) > 1e-9) continue;
    if (n === 0) return '0';
    const g = gcd(Math.abs(n), d);
    const N = n / g, D = d / g, a = Math.abs(N), s = N < 0 ? '-' : '';
    if (D === 1) return `${s}${a === 1 ? '' : a}\\pi`;
    return `${s}\\dfrac{${a === 1 ? '' : a}\\pi}{${D}}`;
  }
  return null;
}
const deg = (v) => (v * 180) / P;
const near = (u, v) => Math.abs(u - v) < 1e-9;
/** Endpoints of {x : lo ≤ a·x + b ≤ hi} for a ≠ 0. */
const linDom = (a, b, lo = -1, hi = 1) => [(lo - b) / a, (hi - b) / a].sort((u, v) => u - v);
/** Numerical domain scan: is f defined (not NaN) at x? */
const ok = (g, x) => !Number.isNaN(g(x));

// ---------------------------------------------------------------- figures used by questions
const gAcosBare = plot({ x: [-1.5, 1.5], y: [-0.5, 3.5], fns: [{ expr: 'acos(x)', label: 'curve', domain: [-1, 1] }], pts: [[-1, P, r`$(-1, \pi)$`], [0, P / 2, r`$\left(0, \dfrac{\pi}{2}\right)$`], [1, 0, r`$(1, 0)$`]] }, 'A curve defined only from x equal to minus 1 to x equal to 1. It starts high at the point (minus 1, pi), passes through (0, pi over 2) and falls to (1, 0), decreasing all the way.', 'Which inverse function is this?');
export const gAtan = plot({ x: [-6, 6], y: [-2, 2], fns: [{ expr: 'atan(x)', label: r`$y = \tan^{-1} x$` }], pts: [[0, 0, '(0, 0)'], [1, P / 4, r`$\left(1, \dfrac{\pi}{4}\right)$`], [-1, -P / 4, r`$\left(-1, -\dfrac{\pi}{4}\right)$`]] }, 'The graph of y equals tan inverse x over x from minus 6 to 6: an S-shaped curve rising through the origin, flattening towards the dashed horizontal lines y equals pi over 2 above and y equals minus pi over 2 below, without ever touching them.', r`$y = \tan^{-1} x$ with its asymptotes $y = \pm\dfrac{\pi}{2}$.`);
gAtan.spec.hlines = [{ y: P / 2, label: r`$y = \dfrac{\pi}{2}$`, dashed: true }, { y: -P / 2, label: r`$y = -\dfrac{\pi}{2}$`, dashed: true }];
const gBoth = plot({ x: [-1.5, 1.5], y: [-2, 3.5], fns: [{ expr: 'asin(x)', label: r`$y = \sin^{-1} x$`, domain: [-1, 1] }, { expr: 'acos(x)', label: r`$y = \cos^{-1} x$`, domain: [-1, 1] }], pts: [[-1, -P / 2, r`$\left(-1, -\dfrac{\pi}{2}\right)$`], [-1, P, r`$(-1, \pi)$`], [1, P / 2, r`$\left(1, \dfrac{\pi}{2}\right)$`], [Math.SQRT1_2, P / 4, 'K']] }, 'Two curves on the same axes for x from minus 1 to 1: y equals sin inverse x rising from (minus 1, minus pi over 2) to (1, pi over 2), and y equals cos inverse x falling from (minus 1, pi) to (1, 0). They cross at one point K.', r`$y = \sin^{-1} x$ (rising) and $y = \cos^{-1} x$ (falling) cross at $K$.`);

// =============================================================== MCQ
Q('m01', mk.mcq({ stem: r`The range of the principal value branch of $\sin^{-1} x$ is`, opts: [r`$\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$`, r`$[0, \pi]$`, r`$\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$`, r`$[-1, 1]$`], key: 'a', sol: r`Sine is one-one on $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$ and takes every value in $[-1, 1]$ there, so this closed interval is the range of $\sin^{-1}$. Option (d) is its domain; (c) is the range of $\tan^{-1}$.`, d: 1, c: 'recall', t: [1], time: 30 }), (C) => { C.which([[-P / 2, P / 2], [0, P], [-P / 2 + 1e-3, P / 2 - 1e-3], [-1, 1]], [Math.asin(-1), Math.asin(1)]); });
Q('m02', mk.mcq({ stem: r`The domain of $\cos^{-1} x$ is`, opts: [r`$\mathbb{R}$`, r`$[-1, 1]$`, r`$[0, \pi]$`, r`$(-1, 1)$`], key: 'b', sol: r`$\cos^{-1} x$ is the angle in $[0, \pi]$ whose cosine is $x$; cosine only takes values from $-1$ to $1$ (both included), so the domain is $[-1, 1]$. Option (c) is the range.`, d: 1, c: 'recall', t: [1], time: 30 }), (C) => { C.assert(ok(Math.acos, -1) && ok(Math.acos, 1) && !ok(Math.acos, 1.0001) && !ok(Math.acos, -1.0001), 'acos defined exactly on [-1, 1]'); C.key('b'); });
Q('m03', mk.mcq({ stem: r`The principal value of $\cos^{-1}\left(-\dfrac{\sqrt{3}}{2}\right)$ is`, opts: [r`$\dfrac{5\pi}{6}$`, r`$-\dfrac{\pi}{6}$`, r`$\dfrac{\pi}{6}$`, r`$\dfrac{7\pi}{6}$`], key: 'a', sol: r`We need $y \in [0, \pi]$ with $\cos y = -\dfrac{\sqrt3}{2}$. Since $\cos\dfrac{\pi}{6} = \dfrac{\sqrt3}{2}$, the angle is $\pi - \dfrac{\pi}{6} = \dfrac{5\pi}{6}$, which lies in $[0, \pi]$. Options (b) and (d) are outside the range.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => C.which([5 * P / 6, -P / 6, P / 6, 7 * P / 6], Math.acos(-S3 / 2)));
Q('m04', mk.mcq({ stem: r`The principal value of $\tan^{-1}(-\sqrt{3})$ is`, opts: [r`$\dfrac{2\pi}{3}$`, r`$-\dfrac{\pi}{3}$`, r`$-\dfrac{\pi}{6}$`, r`$\dfrac{\pi}{3}$`], key: 'b', sol: r`$\tan\dfrac{\pi}{3} = \sqrt3$, so $\tan\left(-\dfrac{\pi}{3}\right) = -\sqrt3$, and $-\dfrac{\pi}{3}$ lies in $\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$. Option (a) also has tangent $-\sqrt3$ but is outside the principal range.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => C.which([2 * P / 3, -P / 3, -P / 6, P / 3], Math.atan(-S3)));
Q('m05', mk.mcq({ stem: r`The principal value of $\sin^{-1}\left(-\dfrac{1}{\sqrt{2}}\right)$ is`, opts: [r`$\dfrac{5\pi}{4}$`, r`$\dfrac{3\pi}{4}$`, r`$-\dfrac{\pi}{4}$`, r`$\dfrac{7\pi}{4}$`], key: 'c', sol: r`$\sin\left(-\dfrac{\pi}{4}\right) = -\dfrac{1}{\sqrt2}$ and $-\dfrac{\pi}{4} \in \left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$. Options (a) and (d) also have this sine, but lie outside the principal range; option (b) has sine $+\dfrac{1}{\sqrt2}$.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => C.which([5 * P / 4, 3 * P / 4, -P / 4, 7 * P / 4], Math.asin(-1 / S2)));
Q('m06', mk.mcq({ stem: r`The principal value of $\sec^{-1}(-2)$ is`, opts: [r`$-\dfrac{\pi}{3}$`, r`$\dfrac{2\pi}{3}$`, r`$\dfrac{4\pi}{3}$`, r`$\dfrac{\pi}{3}$`], key: 'b', sol: r`We need $y \in [0, \pi]$, $y \ne \dfrac{\pi}{2}$, with $\sec y = -2$, i.e. $\cos y = -\dfrac12$. That angle is $\dfrac{2\pi}{3}$. Option (d) has secant $+2$; (a) and (c) are outside the range.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => C.which([-P / 3, 2 * P / 3, 4 * P / 3, P / 3], asec(-2)));
Q('m07', mk.mcq({ stem: r`The principal value of $\cot^{-1}(-1)$ is`, opts: [r`$-\dfrac{\pi}{4}$`, r`$\dfrac{\pi}{4}$`, r`$\dfrac{5\pi}{4}$`, r`$\dfrac{3\pi}{4}$`], key: 'd', sol: r`The principal branch of $\cot^{-1}$ has range $(0, \pi)$. $\cot\dfrac{3\pi}{4} = -1$ and $\dfrac{3\pi}{4} \in (0, \pi)$. Option (a) has cotangent $-1$ but is negative, so it is not in the range.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => C.which([-P / 4, P / 4, 5 * P / 4, 3 * P / 4], acot(-1)));
Q('m08', mk.mcq({ stem: r`The principal value of $\operatorname{cosec}^{-1}(-\sqrt{2})$ is`, opts: [r`$-\dfrac{\pi}{4}$`, r`$\dfrac{5\pi}{4}$`, r`$\dfrac{3\pi}{4}$`, r`$-\dfrac{3\pi}{4}$`], key: 'a', sol: r`The range is $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$ without $0$. $\operatorname{cosec}\left(-\dfrac{\pi}{4}\right) = -\sqrt2$, and $-\dfrac{\pi}{4}$ is in that range.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => C.which([-P / 4, 5 * P / 4, 3 * P / 4, -3 * P / 4], acsc(-S2)));
Q('m09', mk.mcq({ stem: r`The value of $\sin^{-1}\left(\sin\dfrac{5\pi}{6}\right)$ is`, opts: [r`$\dfrac{5\pi}{6}$`, r`$\dfrac{\pi}{6}$`, r`$-\dfrac{\pi}{6}$`, r`$\dfrac{\pi}{3}$`], key: 'b', sol: r`$\sin\dfrac{5\pi}{6} = \dfrac12$, and the angle in $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$ with sine $\dfrac12$ is $\dfrac{\pi}{6}$. Option (a) is a trap: $\dfrac{5\pi}{6}$ is not in the principal range.`, d: 3, c: 'application', t: [1], time: 75 }), (C) => C.which([5 * P / 6, P / 6, -P / 6, P / 3], Math.asin(Math.sin(5 * P / 6))));
Q('m10', mk.mcq({ stem: r`The value of $\cos^{-1}\left(\cos\dfrac{4\pi}{3}\right)$ is`, opts: [r`$\dfrac{4\pi}{3}$`, r`$-\dfrac{2\pi}{3}$`, r`$\dfrac{2\pi}{3}$`, r`$\dfrac{\pi}{3}$`], key: 'c', sol: r`$\cos\dfrac{4\pi}{3} = -\dfrac12$. The angle in $[0, \pi]$ with cosine $-\dfrac12$ is $\dfrac{2\pi}{3}$. Option (a) lies outside $[0, \pi]$; (d) has cosine $+\dfrac12$.`, d: 3, c: 'application', t: [1], time: 75 }), (C) => C.which([4 * P / 3, -2 * P / 3, 2 * P / 3, P / 3], Math.acos(Math.cos(4 * P / 3))));
Q('m11', mk.mcq({ stem: r`The value of $\tan^{-1}\left(\tan\dfrac{5\pi}{6}\right)$ is`, opts: [r`$\dfrac{5\pi}{6}$`, r`$-\dfrac{\pi}{6}$`, r`$\dfrac{\pi}{6}$`, r`$-\dfrac{5\pi}{6}$`], key: 'b', sol: r`$\tan\dfrac{5\pi}{6} = -\dfrac{1}{\sqrt3}$. The angle in $\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$ with that tangent is $-\dfrac{\pi}{6}$.`, d: 3, c: 'application', t: [1], time: 75 }), (C) => C.which([5 * P / 6, -P / 6, P / 6, -5 * P / 6], Math.atan(Math.tan(5 * P / 6))));
Q('m12', mk.mcq({ stem: r`The domain of $f(x) = \sin^{-1}(3x - 2)$ is`, opts: [r`$\left[\dfrac{1}{3}, 1\right]$`, r`$[-1, 1]$`, r`$\left[-\dfrac{1}{3}, 1\right]$`, r`$[1, 3]$`], key: 'a', sol: r`Need $-1 \le 3x - 2 \le 1$, i.e. $1 \le 3x \le 3$, so $\dfrac13 \le x \le 1$.`, d: 2, c: 'application', t: [1], time: 60 }), (C) => { const dom = linDom(3, -2); C.which([[1 / 3, 1], [-1, 1], [-1 / 3, 1], [1, 3]], dom); const g = (x) => Math.asin(3 * x - 2); C.assert(ok(g, 1 / 3) && ok(g, 1) && !ok(g, 0.33) && !ok(g, 1.001), 'scan'); });
Q('m13', mk.mcq({ stem: r`The value of $\sin\left(\cos^{-1}\dfrac{8}{17}\right)$ is`, opts: [r`$\dfrac{8}{17}$`, r`$\dfrac{15}{17}$`, r`$\dfrac{15}{8}$`, r`$\dfrac{17}{15}$`], key: 'b', sol: r`Let $\theta = \cos^{-1}\dfrac{8}{17}$, so $\cos\theta = \dfrac{8}{17}$ with $\theta$ in $\left[0, \dfrac{\pi}{2}\right]$. In a right triangle with adjacent side $8$ and hypotenuse $17$, the opposite side is $\sqrt{289 - 64} = 15$, so $\sin\theta = \dfrac{15}{17}$.`, d: 3, c: 'application', t: [1], time: 90 }), (C) => C.which([8 / 17, 15 / 17, 15 / 8, 17 / 15], Math.sin(Math.acos(8 / 17))));
Q('m14', mk.mcq({ stem: r`The graph of $y = \tan^{-1} x$ has the horizontal asymptotes`, opts: [r`$y = \pm 1$`, r`$y = \pm\dfrac{\pi}{2}$`, r`$x = \pm\dfrac{\pi}{2}$`, r`$y = 0$ and $y = \pi$`], key: 'b', sol: r`As $x$ grows large and positive, $\tan^{-1} x$ approaches $\dfrac{\pi}{2}$; as $x$ grows large and negative, it approaches $-\dfrac{\pi}{2}$, never reaching either. Option (c) gives the vertical asymptotes of $y = \tan x$.`, d: 1, c: 'recall', t: [2], time: 45 }), (C) => { C.assert(Math.abs(Math.atan(1e9) - P / 2) < 1e-6 && Math.atan(1e9) < P / 2 && Math.abs(Math.atan(-1e9) + P / 2) < 1e-6, 'limits ±π/2'); C.key('b'); });
Q('m15', mk.mcq({ stem: r`The graph shown passes through $(-1, \pi)$, $\left(0, \dfrac{\pi}{2}\right)$ and $(1, 0)$. It is the graph of`, assets: [gAcosBare], opts: [r`$y = \sin^{-1} x$`, r`$y = \cos^{-1} x$`, r`$y = \tan^{-1} x$`, r`$y = \cot^{-1} x$`], key: 'b', sol: r`Only $\cos^{-1}$ gives $\cos^{-1}(-1) = \pi$, $\cos^{-1} 0 = \dfrac{\pi}{2}$ and $\cos^{-1} 1 = 0$. $\sin^{-1}(-1) = -\dfrac{\pi}{2}$; $\tan^{-1}$ and $\cot^{-1}$ are defined for all real $x$, while this curve stops at $x = \pm 1$.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { const pts = [[-1, P], [0, P / 2], [1, 0]]; C.which([Math.asin, Math.acos, Math.atan, acot].map((g) => pts.every(([x, y]) => near(g(x), y))), true); });
Q('m16', mk.mcq({ stem: r`Which point lies on the graph of $y = \sin^{-1} x$?`, opts: [r`$\left(\dfrac{1}{2}, \dfrac{\pi}{3}\right)$`, r`$\left(\dfrac{\sqrt{3}}{2}, \dfrac{\pi}{3}\right)$`, r`$(1, \pi)$`, r`$\left(-1, \dfrac{\pi}{2}\right)$`], key: 'b', sol: r`$\sin\dfrac{\pi}{3} = \dfrac{\sqrt3}{2}$ and $\dfrac{\pi}{3}$ is in the principal range, so $\left(\dfrac{\sqrt3}{2}, \dfrac{\pi}{3}\right)$ is on the graph. Option (a) is on $y = \cos^{-1} x$; (c) and (d) have the wrong heights ($\sin^{-1} 1 = \dfrac{\pi}{2}$, $\sin^{-1}(-1) = -\dfrac{\pi}{2}$).`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => C.which([[0.5, P / 3], [S3 / 2, P / 3], [1, P], [-1, P / 2]].map(([x, y]) => near(Math.asin(x), y)), true));
Q('m17', mk.mcq({ stem: r`The graph of $y = \cos^{-1} x$ can be obtained from the graph of $y = \cos x$, $0 \le x \le \pi$, by reflecting it in`, opts: [r`the $x$-axis`, r`the $y$-axis`, r`the line $y = x$`, r`the origin`], key: 'c', sol: r`If $(a, b)$ is on $y = \cos x$ with $0 \le a \le \pi$, then $\cos^{-1} b = a$, so $(b, a)$ is on $y = \cos^{-1} x$. Swapping the coordinates is reflection in the line $y = x$.`, d: 2, c: 'understanding', t: [2], time: 45 }), (C) => { C.assert([0.3, 1, 2, 3].every((a) => near(Math.acos(Math.cos(a)), a)), '(a, cos a) ↦ (cos a, a)'); C.key('c'); });
Q('m18', mk.mcq({ stem: r`The range of $y = 2\sin^{-1} x + \dfrac{\pi}{2}$ is`, opts: [r`$\left[-\dfrac{\pi}{2}, \dfrac{3\pi}{2}\right]$`, r`$[0, \pi]$`, r`$[-\pi, \pi]$`, r`$\left[\dfrac{\pi}{2}, \dfrac{3\pi}{2}\right]$`], key: 'a', sol: r`$-\dfrac{\pi}{2} \le \sin^{-1} x \le \dfrac{\pi}{2}$, so $-\pi \le 2\sin^{-1} x \le \pi$ and, adding $\dfrac{\pi}{2}$, $-\dfrac{\pi}{2} \le y \le \dfrac{3\pi}{2}$. Both ends are reached at $x = -1$ and $x = 1$.`, d: 3, c: 'application', t: [1, 2], time: 75 }), (C) => { const g = (x) => 2 * Math.asin(x) + P / 2; C.which([[-P / 2, 3 * P / 2], [0, P], [-P, P], [P / 2, 3 * P / 2]], [g(-1), g(1)]); });

// =============================================================== assertion-reason
Q('ar1', mk.ar({ a: r`The principal value of $\cos^{-1}\left(-\dfrac12\right)$ is $\dfrac{2\pi}{3}$.`, r: r`The principal value branch of $\cos^{-1}$ has range $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$.`, key: 'c', sol: r`A: $\cos\dfrac{2\pi}{3} = -\dfrac12$ and $\dfrac{2\pi}{3} \in [0, \pi]$, so A is true. R is false: the range of $\cos^{-1}$ is $[0, \pi]$; the interval in R belongs to $\sin^{-1}$.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(near(Math.acos(-0.5), 2 * P / 3), 'acos(-1/2) = 2π/3'); C.key('c'); });
Q('ar2', mk.ar({ a: r`$\sin^{-1}\left(\sin\dfrac{3\pi}{4}\right) = \dfrac{3\pi}{4}$.`, r: r`$\sin^{-1}(\sin\theta) = \theta$ holds only when $\theta$ lies in $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$.`, key: 'd', sol: r`$\sin\dfrac{3\pi}{4} = \dfrac{1}{\sqrt2}$ and the principal value of $\sin^{-1}\dfrac{1}{\sqrt2}$ is $\dfrac{\pi}{4}$, so A is false. R is true: outside the principal range the output must differ from $\theta$, because $\sin^{-1}$ only returns angles in that range.`, d: 3, c: 'analysis', t: [1] }), (C) => { C.assert(near(Math.asin(Math.sin(3 * P / 4)), P / 4), 'value π/4'); C.key('d'); });
Q('ar3', mk.ar({ a: r`The graph of $y = \tan^{-1} x$ never meets the line $y = 2$.`, r: r`The range of $\tan^{-1}$ is $\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$, and $\dfrac{\pi}{2} < 2$.`, key: 'a', sol: r`Every value of $\tan^{-1} x$ is less than $\dfrac{\pi}{2} \approx 1.57$, which is less than $2$. So the curve stays below $y = 2$. R is exactly the reason.`, d: 2, c: 'understanding', t: [2] }), (C) => { C.assert(P / 2 < 2 && Math.atan(1e12) < 2, 'atan < π/2 < 2'); C.key('a'); });
Q('ar4', mk.ar({ a: r`$\cos^{-1}(1.5)$ is not defined.`, r: r`Every value of $\cos^{-1} x$ lies in $[0, \pi]$.`, key: 'b', sol: r`A is true: $1.5$ is outside the domain $[-1, 1]$, since no angle has cosine $1.5$. R is true too, but it is about the output (range), not about which inputs are allowed, so it does not explain A.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(Number.isNaN(Math.acos(1.5)), 'acos(1.5) NaN'); C.key('b'); });
Q('ar5', mk.ar({ a: r`$\tan^{-1}(-1) = -\dfrac{\pi}{4}$.`, r: r`$\tan\left(-\dfrac{\pi}{4}\right) = -1$ and $-\dfrac{\pi}{4}$ lies in $\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$, the range of the principal branch of $\tan^{-1}$.`, key: 'a', sol: r`By definition, $\tan^{-1}(-1)$ is the angle in $\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$ with tangent $-1$. R states both conditions, so it explains A.`, d: 1, c: 'understanding', t: [1] }), (C) => { C.assert(near(Math.atan(-1), -P / 4), 'atan(-1)'); C.key('a'); });
Q('ar6', mk.ar({ a: r`The sine function restricted to $[0, \pi]$ has no inverse function.`, r: r`$\sin x \ge 0$ for every $x$ in $[0, \pi]$.`, key: 'b', sol: r`A is true: on $[0, \pi]$ sine is not one-one, for example $\sin\dfrac{\pi}{6} = \sin\dfrac{5\pi}{6} = \dfrac12$. R is also true, but being non-negative does not stop a function from having an inverse; the repeated values do. R does not explain A.`, d: 3, c: 'analysis', t: [1] }), (C) => { C.assert(near(Math.sin(P / 6), Math.sin(5 * P / 6)) && [0, 0.5, 1, 2, 3, P].every((x) => Math.sin(x) >= -1e-15), 'not one-one, non-negative'); C.key('b'); });

// =============================================================== true-false
Q('tf1', mk.tf({ stem: r`$\tan^{-1} x$ is defined for every real number $x$.`, key: 't', sol: r`Tangent takes every real value on $\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$, so the domain of $\tan^{-1}$ is $\mathbb{R}$.`, d: 1, c: 'recall', t: [1] }), (C) => { C.assert([-1e6, -3, 0, 7, 1e6].every((x) => ok(Math.atan, x)), 'defined'); C.key('t'); });
Q('tf2', mk.tf({ stem: r`$\sin^{-1} x$ means $\dfrac{1}{\sin x}$.`, key: 'f', sol: r`$\sin^{-1} x$ is the inverse sine (an angle), not a reciprocal; $\dfrac{1}{\sin x}$ is written $\operatorname{cosec} x$ or $(\sin x)^{-1}$.`, d: 1, c: 'recall', t: [1] }), (C) => { C.assert(!near(Math.asin(0.5), 1 / Math.sin(0.5)), 'different'); C.key('f'); });
Q('tf3', mk.tf({ stem: r`The principal value of $\operatorname{cosec}^{-1}(2)$ is $\dfrac{5\pi}{6}$.`, key: 'f', sol: r`$\operatorname{cosec}\dfrac{5\pi}{6} = 2$, but $\dfrac{5\pi}{6}$ is outside $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$. The principal value is $\dfrac{\pi}{6}$.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(near(acsc(2), P / 6), 'π/6'); C.key('f'); });
Q('tf4', mk.tf({ stem: r`The function $y = \cos^{-1} x$ is decreasing on $[-1, 1]$.`, key: 't', sol: r`Its graph falls from $(-1, \pi)$ to $(1, 0)$: a larger input always gives a smaller angle.`, d: 2, c: 'understanding', t: [2] }), (C) => { const xs = Array.from({ length: 201 }, (_, k) => -1 + k / 100); C.assert(xs.every((x, k) => k === 0 || Math.acos(x) < Math.acos(xs[k - 1])), 'strictly decreasing'); C.key('t'); });
Q('tf5', mk.tf({ stem: r`$\cos^{-1}\left(\cos\left(-\dfrac{\pi}{3}\right)\right) = -\dfrac{\pi}{3}$.`, key: 'f', sol: r`$\cos\left(-\dfrac{\pi}{3}\right) = \dfrac12$ and the angle in $[0, \pi]$ with cosine $\dfrac12$ is $\dfrac{\pi}{3}$, not $-\dfrac{\pi}{3}$.`, d: 3, c: 'application', t: [1] }), (C) => { C.assert(near(Math.acos(Math.cos(-P / 3)), P / 3), 'π/3'); C.key('f'); });

// =============================================================== fill in the blank
Q('fb1', mk.fill({ stem: r`Every principal value of $\cot^{-1} x$ lies in the interval ___.`, acc: [[r`$(0, \pi)$`, '(0, π)', '(0, pi)']], sol: r`Cotangent is one-one on $(0, \pi)$ and takes every real value there; $0$ and $\pi$ are excluded because $\cot$ is undefined at them.`, d: 1, c: 'recall', t: [1] }), (C) => { C.assert([-1e6, -1, 0, 1, 1e6].every((x) => acot(x) > 0 && acot(x) < P), 'acot in (0, π)'); C.blank(r`$(0, \pi)$`); });
Q('fb2', mk.fill({ stem: r`The principal value of $\cos^{-1}\left(\dfrac{1}{\sqrt{2}}\right)$ is ___.`, acc: [[r`$\dfrac{\pi}{4}$`, 'π/4', 'pi/4']], sol: r`$\cos\dfrac{\pi}{4} = \dfrac{1}{\sqrt2}$ and the angle lies in $[0, \pi]$, so the answer is $\dfrac{\pi}{4}$.`, d: 2, c: 'understanding', t: [1] }), (C) => C.blank(`$${piTex(Math.acos(1 / S2))}$`));
Q('fb3', mk.fill({ stem: r`If $\sin^{-1} x = -\dfrac{\pi}{6}$, then $x =$ ___.`, acc: [['-1/2', '-0.5', '−1/2', '−0.5']], sol: r`By definition $x = \sin\left(-\dfrac{\pi}{6}\right) = -\dfrac12$; and $-\dfrac{\pi}{6}$ is in the principal range, so this is consistent. Answer: −0.5.`, d: 2, c: 'understanding', t: [1] }), (C) => C.blank(Math.sin(-P / 6)));
Q('fb4', mk.fill({ stem: r`The graph of $y = \tan^{-1} x$ meets the $y$-axis at $y =$ ___.`, acc: [['0']], sol: r`On the $y$-axis $x = 0$, and $\tan^{-1} 0 = 0$: the curve passes through the origin.`, d: 1, c: 'understanding', t: [2] }), (C) => C.blank(Math.atan(0)));
Q('fb5', mk.fill({ stem: r`The domain of $\cos^{-1}(2x + 1)$ is ___.`, acc: [[r`$[-1, 0]$`, '[-1, 0]', '[−1, 0]']], sol: r`Need $-1 \le 2x + 1 \le 1$, i.e. $-2 \le 2x \le 0$, so $-1 \le x \le 0$. Domain: $[-1, 0]$.`, d: 3, c: 'application', t: [1] }), (C) => { const [a, b] = linDom(2, 1); C.blank(`$[${a}, ${b}]$`); });

// =============================================================== numerical
Q('n01', mk.num({ stem: r`Find the principal value of $\tan^{-1}\left(\dfrac{1}{\sqrt{3}}\right)$ in degrees.`, value: 30, unit: 'degrees', sol: r`$\tan 30^\circ = \dfrac{1}{\sqrt3}$ and $30^\circ$ (that is, $\dfrac{\pi}{6}$) lies in the principal range. Answer: $30$.`, scheme: [['30', 1]], d: 2, c: 'understanding', t: [1], time: 45 }), (C) => C.val(deg(Math.atan(1 / S3))));
Q('n02', mk.num({ stem: r`Express $\cot^{-1}\left(-\dfrac{1}{\sqrt{3}}\right)$ (principal value) in degrees.`, value: 120, unit: 'degrees', sol: r`The range is $(0^\circ, 180^\circ)$. $\cot 120^\circ = -\dfrac{1}{\sqrt3}$, so the principal value is $120^\circ$, i.e. $\dfrac{2\pi}{3}$. (Not $-60^\circ$, which is outside the range.)`, scheme: [['120', 1]], d: 2, c: 'understanding', t: [1], time: 60 }), (C) => C.val(deg(acot(-1 / S3))));
Q('n03', mk.num({ stem: r`Find the value of $\sin\left(\cos^{-1}\left(-\dfrac{3}{5}\right)\right)$ as a decimal.`, value: 0.8, sol: r`Let $\theta = \cos^{-1}\left(-\dfrac35\right)$; then $\theta$ lies in $\left(\dfrac{\pi}{2}, \pi\right)$, where sine is positive. $\sin\theta = \sqrt{1 - \dfrac{9}{25}} = \dfrac45 = 0.8$.`, scheme: [['0.8', 1]], d: 3, c: 'application', t: [1], time: 90 }), (C) => C.val(Math.sin(Math.acos(-0.6))));
Q('n04', mk.num({ stem: r`Find the value of $\tan\left(\sin^{-1}(-0.6)\right)$.`, value: -0.75, sol: r`Let $\theta = \sin^{-1}(-0.6)$; then $\theta$ lies in $\left(-\dfrac{\pi}{2}, 0\right)$, where cosine is positive: $\cos\theta = 0.8$. So $\tan\theta = \dfrac{-0.6}{0.8} = -0.75$.`, scheme: [['−0.75', 1]], d: 3, c: 'application', t: [1], time: 90 }), (C) => C.val(Math.tan(Math.asin(-0.6))));
Q('n05', mk.num({ stem: r`If $\tan^{-1}(2x - 3) = \dfrac{\pi}{4}$, find $x$.`, value: 2, sol: r`By definition $2x - 3 = \tan\dfrac{\pi}{4} = 1$, so $2x = 4$ and $x = 2$.`, scheme: [['2', 1]], d: 2, c: 'application', t: [1], time: 60 }), (C) => C.val((Math.tan(P / 4) + 3) / 2));
Q('n06', mk.num({ stem: r`Find, in degrees, the value of $\sin^{-1}\left(\sin\dfrac{5\pi}{4}\right) + \cos^{-1}\left(\cos\dfrac{5\pi}{4}\right)$.`, value: 90, unit: 'degrees', sol: r`$\sin\dfrac{5\pi}{4} = -\dfrac{1}{\sqrt2}$, so the first term is $-\dfrac{\pi}{4} = -45^\circ$. $\cos\dfrac{5\pi}{4} = -\dfrac{1}{\sqrt2}$, so the second term is $\dfrac{3\pi}{4} = 135^\circ$. Sum in degrees: $-45 + 135 = 90$.`, scheme: [['90', 1]], d: 4, c: 'analysis', t: [1], time: 120 }), (C) => C.val(deg(Math.asin(Math.sin(5 * P / 4)) + Math.acos(Math.cos(5 * P / 4)))));

// =============================================================== short answer, 2 marks
Q('s201', mk.short({ marks: 2, stem: r`Find the principal value of $\sin^{-1}\left(-\dfrac{\sqrt{3}}{2}\right)$, stating the range you use.`, model: r`The principal value branch of $\sin^{-1}$ has range $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$. We need $y$ in this range with $\sin y = -\dfrac{\sqrt3}{2}$. Since $\sin\dfrac{\pi}{3} = \dfrac{\sqrt3}{2}$, we get $\sin\left(-\dfrac{\pi}{3}\right) = -\dfrac{\sqrt3}{2}$, and $-\dfrac{\pi}{3}$ is in the range. Principal value: $-\dfrac{\pi}{3}$.`, sol: 'Use the sin-inverse range and a negative angle.', scheme: [['Range of the principal branch stated', 1], ['Principal value with a reason', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), (C) => C.model([piTex(Math.asin(-S3 / 2))]));
Q('s202', mk.short({ marks: 2, stem: r`Find the domain of $f(x) = \cos^{-1}(x^2 - 1)$.`, model: r`$\cos^{-1}$ needs its input in $[-1, 1]$: $-1 \le x^2 - 1 \le 1$, i.e. $0 \le x^2 \le 2$. The left part always holds; the right part gives $-\sqrt{2} \le x \le \sqrt{2}$. Domain: $[-\sqrt{2}, \sqrt{2}]$.`, sol: 'Squeeze the input between −1 and 1.', scheme: [['Inequality $-1 \\le x^2 - 1 \\le 1$', 1], ['Domain $[-\\sqrt{2}, \\sqrt{2}]$', 1]], d: 3, c: 'application', t: [1], time: 120 }), (C) => { const g = (x) => Math.acos(x * x - 1); C.assert(ok(g, S2 - 1e-12) && ok(g, -S2 + 1e-12) && !ok(g, S2 + 1e-6) && !ok(g, -S2 - 1e-6) && ok(g, 0), 'scan ±√2'); C.model([r`[-\sqrt{2}, \sqrt{2}]`]); });
Q('s203', mk.short({ marks: 2, stem: r`Evaluate $2\cos^{-1}(0) - 3\tan^{-1}(1) + \sin^{-1}\left(\dfrac12\right)$.`, model: r`$\cos^{-1} 0 = \dfrac{\pi}{2}$, $\tan^{-1} 1 = \dfrac{\pi}{4}$, $\sin^{-1}\dfrac12 = \dfrac{\pi}{6}$ (all principal values). Value $= \pi - \dfrac{3\pi}{4} + \dfrac{\pi}{6} = \dfrac{12\pi - 9\pi + 2\pi}{12} = \dfrac{5\pi}{12}$.`, sol: 'Principal values first, then combine over 12.', scheme: [['All three principal values', 1], ['Combined value', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), (C) => C.model([piTex(2 * Math.acos(0) - 3 * Math.atan(1) + Math.asin(0.5))]));
Q('s204', mk.short({ marks: 2, stem: r`Solve $\cos^{-1}(2x - 1) = \dfrac{2\pi}{3}$.`, model: r`$\dfrac{2\pi}{3}$ lies in $[0, \pi]$, so by definition $2x - 1 = \cos\dfrac{2\pi}{3} = -\dfrac12$. Then $2x = \dfrac12$ and $x = \dfrac{1}{4}$. Check: $2 \times \dfrac14 - 1 = -\dfrac12$, and $\cos^{-1}\left(-\dfrac12\right) = \dfrac{2\pi}{3}$.`, sol: 'Take cosine of both sides; check the range.', scheme: [['$2x - 1 = \\cos\\dfrac{2\\pi}{3} = -\\dfrac12$', 1], ['$x = \\dfrac14$', 1]], d: 2, c: 'application', t: [1], time: 90 }), (C) => { const x = (Math.cos(2 * P / 3) + 1) / 2; C.assert(near(x, 0.25) && near(Math.acos(2 * x - 1), 2 * P / 3), 'x = 1/4'); C.model([r`\dfrac{1}{4}`]); });
Q('s205', mk.short({ marks: 2, stem: r`The graph of $y = \tan^{-1} x$ is shown. State its domain and range, and write the equations of its horizontal asymptotes.`, assets: [gAtan], model: r`Domain: all real numbers, $\mathbb{R}$ (the curve continues left and right without end). Range: $\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$, an open interval. Horizontal asymptotes: $y = \dfrac{\pi}{2}$ and $y = -\dfrac{\pi}{2}$; the curve gets closer and closer to them but never touches.`, sol: 'Read the extent of the curve on each axis.', scheme: [['Domain and range (open interval)', 1], ['Both asymptotes', 1]], d: 2, c: 'understanding', t: [2], time: 90 }), (C) => { C.assert(Math.atan(1e15) < P / 2 && Math.atan(-1e15) > -P / 2 && Math.abs(Math.atan(1e15) - P / 2) < 1e-9, 'open range, asymptotes'); C.model([r`y = \dfrac{\pi}{2}`, r`y = -\dfrac{\pi}{2}`]); });
Q('s206', mk.short({ marks: 2, stem: r`Find the value of $\cos\left(\sin^{-1}\dfrac{20}{29}\right)$.`, model: r`Let $\theta = \sin^{-1}\dfrac{20}{29}$; since $\dfrac{20}{29} > 0$, $\theta$ lies in $\left(0, \dfrac{\pi}{2}\right)$ and $\cos\theta > 0$. Right triangle: opposite $20$, hypotenuse $29$, adjacent $\sqrt{841 - 400} = \sqrt{441} = 21$. So $\cos\theta = \dfrac{21}{29}$.`, sol: 'Draw the right triangle; the angle is acute.', scheme: [['Third side 21 with the sign of cosine justified', 1], ['$\\dfrac{21}{29}$', 1]], d: 3, c: 'application', t: [1], time: 120 }), (C) => { C.assert(near(Math.cos(Math.asin(20 / 29)), 21 / 29), '21/29'); C.model([21, r`\dfrac{21}{29}`]); });
Q('s207', mk.short({ marks: 2, stem: r`Kavya writes: "$\cos^{-1}\left(\cos\dfrac{5\pi}{3}\right) = \dfrac{5\pi}{3}$, because inverse cosine undoes cosine." Find her error and give the correct value.`, model: r`Error: $\cos^{-1}$ always returns an angle in $[0, \pi]$, and $\dfrac{5\pi}{3}$ is not in $[0, \pi]$, so it cannot be the output. Correct: $\cos\dfrac{5\pi}{3} = \cos\left(2\pi - \dfrac{\pi}{3}\right) = \dfrac12$, and the angle in $[0, \pi]$ with cosine $\dfrac12$ is $\dfrac{\pi}{3}$.`, sol: 'Undoing works only inside the principal range.', scheme: [['Error identified (output must lie in $[0, \\pi]$)', 1], ['Correct value $\\dfrac{\\pi}{3}$', 1]], d: 3, c: 'analysis', t: [1], time: 120 }), (C) => C.model([piTex(Math.acos(Math.cos(5 * P / 3)))]));
Q('s208', mk.short({ marks: 2, stem: r`Find the principal value of $\sec^{-1}(-\sqrt{2})$.`, model: r`The principal branch of $\sec^{-1}$ has range $[0, \pi]$ without $\dfrac{\pi}{2}$. We need $\sec y = -\sqrt2$, i.e. $\cos y = -\dfrac{1}{\sqrt2}$, with $y$ in that range. Since $\cos\dfrac{\pi}{4} = \dfrac{1}{\sqrt2}$, $y = \pi - \dfrac{\pi}{4} = \dfrac{3\pi}{4}$.`, sol: 'Change secant to cosine; second quadrant.', scheme: [['$\\cos y = -\\dfrac{1}{\\sqrt2}$ with the range stated', 1], ['$\\dfrac{3\\pi}{4}$', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), (C) => C.model([piTex(asec(-S2))]));
Q('s209', mk.short({ marks: 2, stem: r`Does the point $\left(-\dfrac12, \dfrac{2\pi}{3}\right)$ lie on the graph of $y = \cos^{-1} x$? On the graph of $y = \sin^{-1} x$? Justify both answers.`, model: r`$\cos^{-1}\left(-\dfrac12\right) = \dfrac{2\pi}{3}$ (cosine $-\dfrac12$, angle in $[0, \pi]$), so **yes**, it is on $y = \cos^{-1} x$. $\sin^{-1}\left(-\dfrac12\right) = -\dfrac{\pi}{6}$, and every value of $\sin^{-1}$ is at most $\dfrac{\pi}{2}$, so the height $\dfrac{2\pi}{3}$ is impossible: **no**, it is not on $y = \sin^{-1} x$.`, sol: 'Compute both functions at x = −1/2.', scheme: [['On the cos-inverse graph, with reason', 1], ['Not on the sin-inverse graph, with reason', 1]], d: 2, c: 'application', t: [2], time: 90 }), (C) => { C.assert(near(Math.acos(-0.5), 2 * P / 3) && !near(Math.asin(-0.5), 2 * P / 3), 'on acos, not on asin'); C.model([piTex(Math.asin(-0.5))]); });

// =============================================================== short answer, 3 marks
Q('s301', mk.short({ marks: 3, stem: r`Evaluate $\sin^{-1}\left(-\dfrac12\right) + 2\cos^{-1}\left(-\dfrac{\sqrt3}{2}\right) - \tan^{-1}(-1)$.`, model: r`Principal values: $\sin^{-1}\left(-\dfrac12\right) = -\dfrac{\pi}{6}$ (in $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$); $\cos^{-1}\left(-\dfrac{\sqrt3}{2}\right) = \dfrac{5\pi}{6}$ (in $[0, \pi]$); $\tan^{-1}(-1) = -\dfrac{\pi}{4}$.

Value $= -\dfrac{\pi}{6} + \dfrac{5\pi}{3} + \dfrac{\pi}{4} = \dfrac{-2\pi + 20\pi + 3\pi}{12} = \dfrac{21\pi}{12} = \dfrac{7\pi}{4}$.`, sol: 'Three principal values, then a common denominator.', scheme: [['$\\sin^{-1}\\left(-\\dfrac12\\right) = -\\dfrac{\\pi}{6}$', 1], ['$\\cos^{-1}\\left(-\\dfrac{\\sqrt3}{2}\\right) = \\dfrac{5\\pi}{6}$ and $\\tan^{-1}(-1) = -\\dfrac{\\pi}{4}$', 1], ['Value $\\dfrac{7\\pi}{4}$', 1]], d: 3, c: 'application', t: [1], time: 150 }), (C) => { const v = Math.asin(-0.5) + 2 * Math.acos(-S3 / 2) - Math.atan(-1); C.model([piTex(Math.asin(-0.5)), piTex(Math.acos(-S3 / 2)), piTex(Math.atan(-1)), piTex(v)]); });
Q('s302', mk.short({ marks: 3, stem: r`Find the domain of $f(x) = \sin^{-1}\left(\dfrac{x - 1}{2}\right) + \cos^{-1}(x - 2)$.`, model: r`First term: $-1 \le \dfrac{x - 1}{2} \le 1 \Rightarrow -2 \le x - 1 \le 2 \Rightarrow -1 \le x \le 3$.

Second term: $-1 \le x - 2 \le 1 \Rightarrow 1 \le x \le 3$.

Both terms must be defined, so take the intersection: $[-1, 3] \cap [1, 3] = [1, 3]$.`, sol: 'Each inverse function needs its input in [−1, 1]; intersect.', scheme: [['First condition $[-1, 3]$', 1], ['Second condition $[1, 3]$', 1], ['Intersection $[1, 3]$', 1]], d: 3, c: 'application', t: [1], time: 150 }), (C) => { const d1 = linDom(0.5, -0.5), d2 = linDom(1, -2); const dom = [Math.max(d1[0], d2[0]), Math.min(d1[1], d2[1])]; C.assert(near(dom[0], 1) && near(dom[1], 3), `${dom}`); C.model([`[${d1[0]}, ${d1[1]}]`, `[${d2[0]}, ${d2[1]}]`, `[${dom[0]}, ${dom[1]}]`]); });
Q('s303', mk.short({ marks: 3, stem: r`Find the values of $\tan^{-1}\left(\tan\dfrac{7\pi}{4}\right)$ and $\cos^{-1}\left(\cos\dfrac{7\pi}{4}\right)$. Why are the two answers different?`, model: r`$\tan\dfrac{7\pi}{4} = -1$ and $\cos\dfrac{7\pi}{4} = \dfrac{1}{\sqrt2}$.

$\tan^{-1}(-1)$: angle in $\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$ with tangent $-1$, so $-\dfrac{\pi}{4}$.

$\cos^{-1}\dfrac{1}{\sqrt2}$: angle in $[0, \pi]$ with cosine $\dfrac{1}{\sqrt2}$, so $\dfrac{\pi}{4}$.

They differ because the two principal branches cover different intervals: $\tan^{-1}$ returns a negative angle here, while $\cos^{-1}$ can never be negative.`, sol: 'Evaluate the inside first, then use each branch.', scheme: [['Inner values $-1$ and $\\dfrac{1}{\\sqrt2}$', 1], ['$-\\dfrac{\\pi}{4}$ and $\\dfrac{\\pi}{4}$', 1], ['Reason: different principal ranges', 1]], d: 3, c: 'application', t: [1], time: 150 }), (C) => C.model([piTex(Math.atan(Math.tan(7 * P / 4))), piTex(Math.acos(Math.cos(7 * P / 4)))]));
Q('s304', mk.short({ marks: 3, stem: r`Sketch the graph of $y = \sin^{-1} x$. Mark at least four points on it, and state its domain, range and whether it is increasing or decreasing.`, model: r`Points (from the principal values): $\left(-1, -\dfrac{\pi}{2}\right)$, $\left(-\dfrac12, -\dfrac{\pi}{6}\right)$, $(0, 0)$, $\left(\dfrac12, \dfrac{\pi}{6}\right)$, $\left(1, \dfrac{\pi}{2}\right)$.

The sketch is a smooth curve from $\left(-1, -\dfrac{\pi}{2}\right)$ through the origin to $\left(1, \dfrac{\pi}{2}\right)$, steep near the ends and flatter near the origin; it is the reflection of $y = \sin x$, $-\dfrac{\pi}{2} \le x \le \dfrac{\pi}{2}$, in the line $y = x$.

Domain $[-1, 1]$; range $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$; increasing throughout.`, sol: 'Use the reflection of the restricted sine curve.', scheme: [['Four or more correct points', 1], ['Correct shape between the end points', 1], ['Domain, range and increasing', 1]], d: 2, c: 'understanding', t: [2], time: 180 }), (C) => { C.assert([[-1, -P / 2], [-0.5, -P / 6], [0, 0], [0.5, P / 6], [1, P / 2]].every(([x, y]) => near(Math.asin(x), y)), 'points'); C.model([piTex(Math.asin(-0.5)), piTex(Math.asin(1))]); });
Q('s305', mk.short({ marks: 3, stem: r`Find the value of $\sin\left(2\tan^{-1}\dfrac{3}{4}\right)$.`, model: r`Let $\theta = \tan^{-1}\dfrac34$, so $\tan\theta = \dfrac34$ with $\theta$ in $\left(0, \dfrac{\pi}{2}\right)$.

Right triangle: opposite $3$, adjacent $4$, hypotenuse $5$; so $\sin\theta = \dfrac35$ and $\cos\theta = \dfrac45$ (both positive since $\theta$ is acute).

Using the double-angle formula from Class 11, $\sin 2\theta = 2\sin\theta\cos\theta = 2 \times \dfrac35 \times \dfrac45 = \dfrac{24}{25}$.`, sol: 'Name the angle, use the triangle, then the double-angle formula.', scheme: [['Angle named, $\\tan\\theta = \\dfrac34$, acute', 1], ['$\\sin\\theta = \\dfrac35$, $\\cos\\theta = \\dfrac45$', 1], ['$\\dfrac{24}{25}$', 1]], d: 4, c: 'application', t: [1], time: 150 }), (C) => { C.assert(near(Math.sin(2 * Math.atan(0.75)), 24 / 25), '24/25'); C.model([r`\dfrac{24}{25}`]); });
Q('s306', mk.short({ marks: 3, stem: r`Use the graph of $y = \cos^{-1} x$ to find all real $x$ for which $\cos^{-1} x > \dfrac{\pi}{3}$.`, model: r`$\cos^{-1} x$ is defined only for $-1 \le x \le 1$, and its graph is decreasing. At $x = \dfrac12$, $\cos^{-1} x = \dfrac{\pi}{3}$.

Since the function decreases, $\cos^{-1} x > \dfrac{\pi}{3}$ exactly when $x < \dfrac12$. Combining with the domain: $-1 \le x < \dfrac12$, i.e. $x \in \left[-1, \dfrac12\right)$.`, sol: 'Boundary point, direction of the graph, domain.', scheme: [['Boundary $x = \\dfrac12$', 1], ['Decreasing so $x < \\dfrac12$', 1], ['Domain applied: $\\left[-1, \\dfrac12\\right)$', 1]], d: 4, c: 'analysis', t: [2], time: 150 }), (C) => { const xs = Array.from({ length: 2001 }, (_, k) => -1 + k / 1000); const sat = xs.filter((x) => Math.acos(x) > P / 3 + 1e-12); C.assert(near(sat[0], -1) && Math.abs(sat[sat.length - 1] - 0.5) < 2e-3 && sat[sat.length - 1] < 0.5, 'set [-1, 1/2)'); C.model([r`\left[-1, \dfrac12\right)`]); });
Q('s307', mk.short({ marks: 3, stem: r`Find the range of $g(x) = 4\tan^{-1} x + \pi$. Is $g(x) = 3\pi$ possible for some real $x$? Explain.`, model: r`For every real $x$, $-\dfrac{\pi}{2} < \tan^{-1} x < \dfrac{\pi}{2}$. Multiply by $4$: $-2\pi < 4\tan^{-1} x < 2\pi$. Add $\pi$: $-\pi < g(x) < 3\pi$.

Range: $(-\pi, 3\pi)$, an open interval.

$g(x) = 3\pi$ would need $\tan^{-1} x = \dfrac{\pi}{2}$, which never happens, so $3\pi$ is **not** possible (it is approached but never reached).`, sol: 'Start from the open range of tan inverse.', scheme: [['Open range of $\\tan^{-1}$ used', 1], ['Range $(-\\pi, 3\\pi)$', 1], ['$3\\pi$ not attained, with reason', 1]], d: 3, c: 'application', t: [1, 2], time: 150 }), (C) => { const g = (x) => 4 * Math.atan(x) + P; C.assert(g(1e15) < 3 * P && g(-1e15) > -P && Math.abs(g(1e15) - 3 * P) < 1e-9, 'open (−π, 3π)'); C.model([r`(-\pi, 3\pi)`]); });
Q('s308', mk.short({ marks: 3, stem: r`Rohan says the principal value of $\operatorname{cosec}^{-1}(-2)$ is $\dfrac{7\pi}{6}$, because $\operatorname{cosec}\dfrac{7\pi}{6} = -2$. Evaluate his claim and give the correct principal value.`, model: r`His calculation $\operatorname{cosec}\dfrac{7\pi}{6} = -2$ is correct, but a principal value must lie in the principal range of $\operatorname{cosec}^{-1}$, which is $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$ without $0$. $\dfrac{7\pi}{6}$ is outside it, so the claim is wrong.

In that range, $\operatorname{cosec} y = -2$ means $\sin y = -\dfrac12$, so $y = -\dfrac{\pi}{6}$. Correct principal value: $-\dfrac{\pi}{6}$.`, sol: 'Check the range before accepting an angle.', scheme: [['Accepts the cosec value but checks the range', 1], ['Range of the principal branch stated', 1], ['Correct value $-\\dfrac{\\pi}{6}$', 1]], d: 3, c: 'evaluation', t: [1], time: 150 }), (C) => { C.assert(near(1 / Math.sin(7 * P / 6), -2), 'cosec 7π/6 = −2'); C.model([piTex(acsc(-2))]); });

// =============================================================== long answer, 5 marks
Q('l01', mk.long({ stem: r`(a) Explain why $\sin x$ must be restricted before it can have an inverse, and state the domain and range of the principal value branch of $\sin^{-1}$.
(b) Find the principal values of $\sin^{-1}\left(\dfrac12\right)$, $\sin^{-1}\left(-\dfrac{1}{\sqrt2}\right)$ and $\sin^{-1}(-1)$.
(c) Hence evaluate $\sin^{-1}\left(\dfrac12\right) - 2\sin^{-1}\left(-\dfrac{1}{\sqrt2}\right) + 3\sin^{-1}(-1)$.`, model: r`(a) On $\mathbb{R}$, $\sin x$ is not one-one: each value in $[-1, 1]$ is taken infinitely often (for example $\sin\dfrac{\pi}{6} = \sin\dfrac{5\pi}{6}$), so "the angle with sine $x$" is not unique. On $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$ sine is one-one and still takes every value in $[-1, 1]$, so it has an inverse there. Principal branch of $\sin^{-1}$: domain $[-1, 1]$, range $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$.

(b) $\sin^{-1}\dfrac12 = \dfrac{\pi}{6}$; $\sin^{-1}\left(-\dfrac{1}{\sqrt2}\right) = -\dfrac{\pi}{4}$; $\sin^{-1}(-1) = -\dfrac{\pi}{2}$ (each in the range, with the right sine).

(c) $\dfrac{\pi}{6} - 2\left(-\dfrac{\pi}{4}\right) + 3\left(-\dfrac{\pi}{2}\right) = \dfrac{\pi}{6} + \dfrac{\pi}{2} - \dfrac{3\pi}{2} = \dfrac{\pi - 6\pi}{6} = -\dfrac{5\pi}{6}$.`, sol: 'Part (c) reuses the three values from part (b).', scheme: [['Not one-one on the real line, with an example', 1], ['Domain and range of the principal branch', 1], ['$\\dfrac{\\pi}{6}$ and $-\\dfrac{\\pi}{4}$', 1], ['$-\\dfrac{\\pi}{2}$', 1], ['Value $-\\dfrac{5\\pi}{6}$', 1]], d: 3, c: 'application', t: [1], time: 420 }), (C) => { const v = Math.asin(0.5) - 2 * Math.asin(-1 / S2) + 3 * Math.asin(-1); C.model([piTex(Math.asin(0.5)), piTex(Math.asin(-1 / S2)), piTex(Math.asin(-1)), piTex(v)]); });
Q('l02', mk.long({ stem: r`Draw the graph of $y = \cos^{-1} x$ using at least five points. From your graph:
(a) state the domain and range;
(b) say whether the function is increasing or decreasing;
(c) find the value of $x$ at which $\cos^{-1} x = \dfrac{\pi}{2}$;
(d) explain how the graph is related to that of $y = \cos x$, $0 \le x \le \pi$.`, model: r`Table of values:

| $x$ | $-1$ | $-\dfrac12$ | $0$ | $\dfrac12$ | $1$ |
|---|---|---|---|---|---|
| $\cos^{-1} x$ | $\pi$ | $\dfrac{2\pi}{3}$ | $\dfrac{\pi}{2}$ | $\dfrac{\pi}{3}$ | $0$ |

Plot these points and join them with a smooth curve from $(-1, \pi)$ down to $(1, 0)$.

(a) Domain $[-1, 1]$; range $[0, \pi]$.
(b) Decreasing: the curve falls from left to right.
(c) $\cos^{-1} x = \dfrac{\pi}{2}$ at $x = 0$ (the curve meets the $y$-axis at height $\dfrac{\pi}{2}$).
(d) It is the reflection of $y = \cos x$, $0 \le x \le \pi$, in the line $y = x$: each point $(a, b)$ on the cosine curve becomes $(b, a)$.`, sol: 'Plot from principal values.', scheme: [['Table with five correct points', 1], ['Smooth decreasing curve through them', 1], ['Domain and range', 1], ['Decreasing; $x = 0$ for $\\dfrac{\\pi}{2}$', 1], ['Reflection in $y = x$', 1]], d: 3, c: 'application', t: [2], time: 480 }), (C) => { C.assert([[-1, P], [-0.5, 2 * P / 3], [0, P / 2], [0.5, P / 3], [1, 0]].every(([x, y]) => near(Math.acos(x), y)), 'table'); C.model([piTex(Math.acos(-0.5)), piTex(Math.acos(0.5)), piTex(Math.acos(-1))]); });
Q('l03', mk.long({ stem: r`Find the values of:
(i) $\sin^{-1}\left(\sin\dfrac{4\pi}{5}\right)$;
(ii) $\cos^{-1}\left(\cos\left(-\dfrac{3\pi}{4}\right)\right)$;
(iii) $\tan^{-1}\left(\tan\dfrac{4\pi}{3}\right)$.
(iv) In which of (i)–(iii) is the answer equal to the angle written inside? Explain using the principal value branches.`, model: r`(i) $\sin\dfrac{4\pi}{5} = \sin\left(\pi - \dfrac{4\pi}{5}\right) = \sin\dfrac{\pi}{5}$, and $\dfrac{\pi}{5} \in \left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$. Value: $\dfrac{\pi}{5}$.

(ii) $\cos\left(-\dfrac{3\pi}{4}\right) = \cos\dfrac{3\pi}{4}$ (cosine is even), and $\dfrac{3\pi}{4} \in [0, \pi]$. Value: $\dfrac{3\pi}{4}$.

(iii) $\tan\dfrac{4\pi}{3} = \tan\left(\pi + \dfrac{\pi}{3}\right) = \tan\dfrac{\pi}{3} = \sqrt3$, and $\dfrac{\pi}{3} \in \left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$. Value: $\dfrac{\pi}{3}$.

(iv) In none of them. The inner angles $\dfrac{4\pi}{5}$, $-\dfrac{3\pi}{4}$, $\dfrac{4\pi}{3}$ all lie outside the respective principal ranges, so the inverse function returns the angle inside its range with the same trigonometric ratio instead.`, sol: 'Move each angle into the right principal range.', scheme: [['(i) $\\dfrac{\\pi}{5}$ with reason', 1], ['(ii) $\\dfrac{3\\pi}{4}$ with reason', 1], ['(iii) inner value $\\sqrt3$', 1], ['(iii) $\\dfrac{\\pi}{3}$', 1], ['(iv) none, with the range argument', 1]], d: 4, c: 'analysis', t: [1], time: 480 }), (C) => { const a = Math.asin(Math.sin(4 * P / 5)), b = Math.acos(Math.cos(-3 * P / 4)), c = Math.atan(Math.tan(4 * P / 3)); C.assert(!near(a, 4 * P / 5) && !near(b, -3 * P / 4) && !near(c, 4 * P / 3), 'none equal'); C.model([piTex(a), piTex(b), piTex(c)]); });
Q('l04', mk.long({ stem: r`Without a calculator, find the exact value of each expression, explaining the sign in each case:
(i) $\cos\left(\tan^{-1}\dfrac{12}{5}\right)$;
(ii) $\sin\left(\cos^{-1}\left(-\dfrac{4}{5}\right)\right)$;
(iii) $\tan\left(\cos^{-1}\left(-\dfrac{4}{5}\right)\right)$;
(iv) $\sec\left(\sin^{-1}\left(-\dfrac{7}{25}\right)\right)$.`, model: r`(i) $\theta = \tan^{-1}\dfrac{12}{5}$ is in $\left(0, \dfrac{\pi}{2}\right)$; triangle $5, 12, 13$: $\cos\theta = \dfrac{5}{13}$.

(ii) $\alpha = \cos^{-1}\left(-\dfrac45\right)$ is in $\left(\dfrac{\pi}{2}, \pi\right)$, where sine is positive: $\sin\alpha = \sqrt{1 - \dfrac{16}{25}} = \dfrac{3}{5}$.

(iii) Same $\alpha$: $\tan\alpha = \dfrac{\sin\alpha}{\cos\alpha} = \dfrac{3/5}{-4/5} = -\dfrac{3}{4}$ (negative in the second quadrant).

(iv) $\beta = \sin^{-1}\left(-\dfrac{7}{25}\right)$ is in $\left(-\dfrac{\pi}{2}, 0\right)$, where cosine is positive: $\cos\beta = \sqrt{1 - \dfrac{49}{625}} = \dfrac{24}{25}$, so $\sec\beta = \dfrac{25}{24}$.`, sol: 'Locate each angle by its principal range before taking square roots.', scheme: [['(i) $\\dfrac{5}{13}$', 1], ['(ii) quadrant of the angle identified', 1], ['(ii) $\\dfrac35$', 1], ['(iii) $-\\dfrac34$', 1], ['(iv) $\\dfrac{25}{24}$ with positive cosine justified', 1]], d: 4, c: 'analysis', t: [1], time: 540 }), (C) => { const al = Math.acos(-0.8); C.assert(near(Math.cos(Math.atan(12 / 5)), 5 / 13) && near(Math.sin(al), 0.6) && near(Math.tan(al), -0.75) && near(1 / Math.cos(Math.asin(-7 / 25)), 25 / 24), 'values'); C.model([r`\dfrac{5}{13}`, r`\dfrac{3}{5}`, r`-\dfrac{3}{4}`, r`\dfrac{25}{24}`]); });
Q('l05', mk.long({ stem: r`Find the domain of each function:
(i) $f(x) = \sin^{-1}(2x + 3)$;
(ii) $g(x) = \cos^{-1}(1 - 2x)$;
(iii) $h(x) = \sin^{-1}(x^2 - 3)$.
(iv) For which real $x$ are both $f(x)$ and $g(x)$ defined?`, model: r`(i) $-1 \le 2x + 3 \le 1 \Rightarrow -4 \le 2x \le -2 \Rightarrow x \in [-2, -1]$.

(ii) $-1 \le 1 - 2x \le 1 \Rightarrow -2 \le -2x \le 0 \Rightarrow 0 \le x \le 1$, so $x \in [0, 1]$.

(iii) $-1 \le x^2 - 3 \le 1 \Rightarrow 2 \le x^2 \le 4$. So $\sqrt2 \le |x| \le 2$: $x \in [-2, -\sqrt2] \cup [\sqrt2, 2]$.

(iv) $[-2, -1] \cap [0, 1]$ is empty: there is no real $x$ for which both are defined.`, sol: 'Squeeze each input between −1 and 1.', scheme: [['(i) $[-2, -1]$', 1], ['(ii) $[0, 1]$', 1], ['(iii) $2 \\le x^2 \\le 4$', 1], ['(iii) union of two intervals', 1], ['(iv) empty intersection', 1]], d: 4, c: 'application', t: [1], time: 480 }), (C) => { const a = linDom(2, 3), b = linDom(-2, 1); const h = (x) => Math.asin(x * x - 3); C.assert(ok(h, 2) && ok(h, S2 + 1e-12) && !ok(h, 1.4) && !ok(h, 0) && ok(h, -1.5) && !ok(h, 2.001), 'h scan'); C.assert(a[1] < b[0], 'disjoint'); C.model([`[${a[0]}, ${a[1]}]`, `[${b[0]}, ${b[1]}]`, r`[-2, -\sqrt2] \cup [\sqrt2, 2]`]); });
Q('l06', mk.long({ stem: r`Solve each equation, or show that it has no solution:
(i) $\sin^{-1}(3x - 1) = -\dfrac{\pi}{6}$;
(ii) $\cos^{-1}\left(\dfrac{x}{2}\right) = \dfrac{5\pi}{6}$;
(iii) $\tan^{-1}(x^2 - 2) = \dfrac{\pi}{4}$;
(iv) $\cos^{-1} x = -\dfrac{\pi}{3}$.`, model: r`(i) $-\dfrac{\pi}{6}$ is in the range of $\sin^{-1}$, so $3x - 1 = \sin\left(-\dfrac{\pi}{6}\right) = -\dfrac12$, giving $3x = \dfrac12$ and $x = \dfrac{1}{6}$.

(ii) $\dfrac{5\pi}{6} \in [0, \pi]$, so $\dfrac{x}{2} = \cos\dfrac{5\pi}{6} = -\dfrac{\sqrt3}{2}$ and $x = -\sqrt{3}$.

(iii) $x^2 - 2 = \tan\dfrac{\pi}{4} = 1$, so $x^2 = 3$ and $x = \pm\sqrt{3}$; both values are valid because $\tan^{-1}$ accepts every real input.

(iv) Every value of $\cos^{-1} x$ lies in $[0, \pi]$, and $-\dfrac{\pi}{3}$ is negative, so the equation has **no solution**.`, sol: 'Check that the right side lies in the principal range first.', scheme: [['(i) $x = \\dfrac16$', 1], ['(ii) $x = -\\sqrt3$', 1], ['(iii) $x^2 = 3$', 1], ['(iii) both signs kept, $x = \\pm\\sqrt3$', 1], ['(iv) no solution, with the range argument', 1]], d: 5, c: 'analysis', t: [1], time: 540 }), (C) => { const x1 = (Math.sin(-P / 6) + 1) / 3, x2 = 2 * Math.cos(5 * P / 6), x3 = Math.sqrt(Math.tan(P / 4) + 2); C.assert(near(x1, 1 / 6) && near(x2, -S3) && near(x3, S3) && near(Math.atan(x3 * x3 - 2), P / 4) && near(Math.asin(3 * x1 - 1), -P / 6) && near(Math.acos(x2 / 2), 5 * P / 6), 'solutions'); C.model([r`x = \dfrac{1}{6}`, r`x = -\sqrt{3}`, r`x = \pm\sqrt{3}`, 'no solution']); });

// =============================================================== case-based (1 + 1 + 2 with an either/or part (c))
caseQ('c01', {
  passage: r`At a railway station in Bhopal, a ramp for wheelchairs and luggage trolleys has a sloping surface $3$ m long and rises $1.5$ m from the platform to a footbridge. Let $\theta$ be the angle the ramp makes with the horizontal platform.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $\theta = \sin^{-1}\dfrac12$. (b) $30$. (c) (i) Second ramp: $\tan^{-1}\dfrac{1}{12}$, which is less than $\dfrac{\pi}{6}$; the first ramp is steeper. Or (ii) $\dfrac{\pi}{4}$; steeper than before.`,
  sol: r`(a) Opposite over hypotenuse: $\sin\theta = \dfrac{1.5}{3} = \dfrac12$. (b) $\sin^{-1}\dfrac12 = \dfrac{\pi}{6} = 30^\circ$. (c) (i) Compare angles. (ii) $\sin\theta = \dfrac{1.5}{1.5\sqrt2} = \dfrac{1}{\sqrt2}$.`,
  children: [
    child('a', mk.mcq({ stem: r`The angle $\theta$ is`, opts: [r`$\sin^{-1}\dfrac12$`, r`$\cos^{-1}\dfrac12$`, r`$\tan^{-1}\dfrac12$`, r`$\sin^{-1} 2$`], key: 'a', sol: r`The rise $1.5$ m is opposite $\theta$ and the $3$ m slope is the hypotenuse: $\sin\theta = \dfrac12$. Option (d) is undefined.`, d: 1, c: 'understanding', t: [1], time: 45 })),
    child('b', mk.num({ stem: r`Find $\theta$ in degrees.`, value: 30, unit: 'degrees', sol: r`$\sin^{-1}\dfrac12 = \dfrac{\pi}{6}$; in degrees $\dfrac{180}{6} = 30$.`, scheme: [['30', 1]], d: 2, c: 'understanding', t: [1], time: 45 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** A second ramp rises $1$ m over a horizontal distance of $12$ m. Write its angle with the horizontal using an inverse trigonometric function and decide which ramp is steeper.`, model: r`Angle $= \tan^{-1}\dfrac{1}{12}$ (rise over horizontal run). Since $\dfrac{1}{12} < \dfrac{1}{\sqrt3} = \tan\dfrac{\pi}{6}$ and $\tan^{-1}$ is increasing, $\tan^{-1}\dfrac{1}{12} < \dfrac{\pi}{6}$. So the first ramp is steeper.`, sol: 'Express as an inverse tangent; compare using the increasing graph.', scheme: [['$\\tan^{-1}\\dfrac{1}{12}$', 1], ['Comparison: first ramp steeper', 1]], d: 3, c: 'application', t: [1, 2], time: 150 }), [
      mk.short({ marks: 2, stem: r`**(ii)** The ramp is rebuilt with the same rise of $1.5$ m but a sloping length of $1.5\sqrt{2}$ m. Find the new angle and say whether the ramp is now steeper or gentler.`, model: r`$\sin\theta = \dfrac{1.5}{1.5\sqrt2} = \dfrac{1}{\sqrt2}$, so $\theta = \sin^{-1}\dfrac{1}{\sqrt2} = \dfrac{\pi}{4}$. Since $\dfrac{\pi}{4} > \dfrac{\pi}{6}$, the rebuilt ramp is steeper.`, sol: 'Opposite over hypotenuse again.', scheme: [['$\\theta = \\dfrac{\\pi}{4}$', 1], ['Steeper, with comparison', 1]], d: 3, c: 'application', t: [1], time: 150 }),
    ]),
  ],
}, (C) => { const th = Math.asin(1.5 / 3); C.child('a').which([Math.asin(0.5), Math.acos(0.5), Math.atan(0.5), Math.asin(2)], th); C.child('b').val(deg(th)); C.child('c').assert(Math.atan(1 / 12) < th, 'gentler'); C.child('c').model([r`\tan^{-1}\dfrac{1}{12}`]); C.child('cii').model([piTex(Math.asin(1.5 / (1.5 * S2)))]); });
caseQ('c02', {
  passage: r`The lamp of a lighthouse on the Konkan coast is $30$ m above sea level. A fishing boat is $d$ metres from the foot of the lighthouse. The angle of depression of the boat from the lamp is $\theta = \tan^{-1}\left(\dfrac{30}{d}\right)$.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $\dfrac{\pi}{6}$. (b) $45$. (c) (i) $d = 10\sqrt3 \approx 17.32$ m. Or (ii) The range of $\tan^{-1}$ is $\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$, so $\theta < \dfrac{\pi}{2}$ for every $d > 0$.`,
  sol: r`(a) $\tan^{-1}\dfrac{30}{30\sqrt3} = \tan^{-1}\dfrac{1}{\sqrt3}$. (b) $\tan^{-1} 1$. (c) (i) $\dfrac{30}{d} = \tan\dfrac{\pi}{3}$. (ii) Use the asymptote of the graph.`,
  children: [
    child('a', mk.mcq({ stem: r`When the boat is $30\sqrt3$ m away, $\theta$ equals`, opts: [r`$\dfrac{\pi}{6}$`, r`$\dfrac{\pi}{3}$`, r`$\dfrac{\pi}{4}$`, r`$\dfrac{\pi}{2}$`], key: 'a', sol: r`$\theta = \tan^{-1}\dfrac{30}{30\sqrt3} = \tan^{-1}\dfrac{1}{\sqrt3} = \dfrac{\pi}{6}$.`, d: 2, c: 'understanding', t: [1], time: 60 })),
    child('b', mk.num({ stem: r`Find $\theta$ in degrees when the boat is $30$ m away.`, value: 45, unit: 'degrees', sol: r`$\theta = \tan^{-1} 1 = \dfrac{\pi}{4}$; in degrees $\dfrac{180}{4} = 45$.`, scheme: [['45', 1]], d: 2, c: 'understanding', t: [1], time: 45 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** How far is the boat when the angle of depression is $\dfrac{\pi}{3}$? Give the exact distance and a decimal approximation.`, model: r`$\tan^{-1}\left(\dfrac{30}{d}\right) = \dfrac{\pi}{3}$ with $\dfrac{\pi}{3}$ in the principal range, so $\dfrac{30}{d} = \tan\dfrac{\pi}{3} = \sqrt3$. Then $d = \dfrac{30}{\sqrt3} = 10\sqrt3 \approx 17.32$ m.`, sol: 'Take tangent of both sides.', scheme: [['$\\dfrac{30}{d} = \\sqrt3$', 1], ['$d = 10\\sqrt3 \\approx 17.32$ m', 1]], d: 3, c: 'application', t: [1], time: 120 }), [
      mk.short({ marks: 2, stem: r`**(ii)** Using the graph of $y = \tan^{-1} x$, explain why the angle of depression is always less than $\dfrac{\pi}{2}$, however close the boat comes, and what happens to $\theta$ as the boat moves away.`, model: r`$\theta = \tan^{-1}\left(\dfrac{30}{d}\right)$, and the graph of $y = \tan^{-1} x$ stays below its asymptote $y = \dfrac{\pi}{2}$ for every real $x$. So even when $\dfrac{30}{d}$ is very large (boat very close), $\theta < \dfrac{\pi}{2}$. As $d$ increases, $\dfrac{30}{d}$ decreases, and since $\tan^{-1}$ is increasing, $\theta$ decreases towards $0$.`, sol: 'Asymptote and the increasing nature of the graph.', scheme: [['Bound by the asymptote $\\dfrac{\\pi}{2}$', 1], ['$\\theta$ decreases as $d$ increases, with reason', 1]], d: 3, c: 'analysis', t: [2], time: 150 }),
    ]),
  ],
}, (C) => { const th = (d) => Math.atan(30 / d); C.child('a').which([P / 6, P / 3, P / 4, P / 2], th(30 * S3)); C.child('b').val(deg(th(30))); const d = 30 / Math.tan(P / 3); C.child('c').assert(near(d, 10 * S3) && Math.abs(d - 17.32) < 0.005, 'd = 10√3'); C.child('c').model([17.32]); C.child('cii').assert(th(1e-9) < P / 2 && th(100) < th(50), 'bounded, decreasing'); C.child('cii').model([r`y = \dfrac{\pi}{2}`]); });
caseQ('c03', {
  passage: r`A painter in Jaipur leans a $6$ m ladder against the vertical wall of a haveli. The foot of the ladder is $3$ m from the wall on level ground. Let $\alpha$ be the angle between the ladder and the ground. For safety, the painter's contractor asks that $\alpha$ lie between $\cos^{-1}\dfrac12$ and $\cos^{-1}\dfrac14$.`,
  d: 4, c: 'application',
  model: r`(a) Option (a): $\cos^{-1}\dfrac12$. (b) about $5.2$ m. (c) (i) Foot between $1.5$ m and $3$ m from the wall. Or (ii) $\alpha = \dfrac{\pi}{4}$; not safe (too shallow).`,
  sol: r`(a) Adjacent over hypotenuse. (b) $6\sin\dfrac{\pi}{3} = 3\sqrt3$. (c) (i) Foot distance $= 6\cos\alpha$; cosine decreases on $[0, \pi]$. (ii) Compare with $\dfrac{\pi}{3}$.`,
  children: [
    child('a', mk.mcq({ stem: r`The angle $\alpha$ is`, opts: [r`$\cos^{-1}\dfrac12$`, r`$\sin^{-1}\dfrac12$`, r`$\tan^{-1}\dfrac12$`, r`$\cos^{-1} 2$`], key: 'a', sol: r`The $3$ m along the ground is adjacent to $\alpha$ and the ladder is the hypotenuse: $\cos\alpha = \dfrac36 = \dfrac12$.`, d: 1, c: 'understanding', t: [1], time: 45 })),
    child('b', mk.num({ stem: r`How high up the wall does the ladder reach? Give your answer in metres, correct to one decimal place.`, value: 5.2, tol: 0.01, unit: 'm', sol: r`$\alpha = \cos^{-1}\dfrac12 = \dfrac{\pi}{3}$; height $= 6\sin\dfrac{\pi}{3} = 3\sqrt3$, and $6 \times 0.866 = 5.196$, so about $5.2$ m.`, scheme: [['5.2', 1]], d: 2, c: 'application', t: [1], time: 75 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** Find the range of distances of the foot of the ladder from the wall that meet the safety rule.`, model: r`Foot distance $= 6\cos\alpha$. With $\cos^{-1}\dfrac12 \le \alpha \le \cos^{-1}\dfrac14$, and cosine decreasing on $[0, \pi]$, we get $\dfrac14 \le \cos\alpha \le \dfrac12$. So the distance lies between $6 \times \dfrac14 = 1.5$ m and $6 \times \dfrac12 = 3$ m.`, sol: 'Translate the angle bounds into cosine bounds.', scheme: [['$\\dfrac14 \\le \\cos\\alpha \\le \\dfrac12$ (order reversed)', 1], ['Between 1.5 m and 3 m', 1]], d: 4, c: 'analysis', t: [1, 2], time: 150 }), [
      mk.short({ marks: 2, stem: r`**(ii)** The foot is moved to $3\sqrt2$ m from the wall. Find the new angle $\alpha$ and decide whether the ladder now meets the safety rule.`, model: r`$\cos\alpha = \dfrac{3\sqrt2}{6} = \dfrac{1}{\sqrt2}$, so $\alpha = \cos^{-1}\dfrac{1}{\sqrt2} = \dfrac{\pi}{4}$. The rule needs $\alpha \ge \cos^{-1}\dfrac12 = \dfrac{\pi}{3}$, and $\dfrac{\pi}{4} < \dfrac{\pi}{3}$: the ladder is too shallow and does **not** meet the rule.`, sol: 'Find the angle, compare with the lower bound.', scheme: [['$\\alpha = \\dfrac{\\pi}{4}$', 1], ['Not safe, with comparison', 1]], d: 3, c: 'application', t: [1], time: 150 }),
    ]),
  ],
}, (C) => { const al = Math.acos(3 / 6); C.child('a').which([Math.acos(0.5), Math.asin(0.5), Math.atan(0.5), Math.acos(2)], al); C.child('b').val(6 * Math.sin(al), 0.01); const lo = 6 * Math.cos(Math.acos(0.25)), hi = 6 * Math.cos(Math.acos(0.5)); C.child('c').assert(near(lo, 1.5) && near(hi, 3), 'distances'); C.child('c').model([lo, hi]); const a2 = Math.acos((3 * S2) / 6); C.child('cii').assert(a2 < Math.acos(0.5), 'too shallow'); C.child('cii').model([piTex(a2)]); });
caseQ('c04', {
  passage: r`For a class project in Kota, Ananya plots $y = \sin^{-1} x$ and $y = \cos^{-1} x$ on the same axes for $-1 \le x \le 1$ (figure). The two curves cross at one point $K$.`,
  assets: [gBoth],
  d: 3, c: 'application',
  model: r`(a) Option (a): $[0, \pi]$. (b) $45$. (c) (i) $\dfrac{1}{\sqrt2} < x \le 1$. Or (ii) $\dfrac{\pi}{2}$ at $x = 0$ and $\dfrac{3\pi}{2}$ at $x = -1$.`,
  sol: r`(a) The falling curve is $\cos^{-1}$. (b) At $K$: $x = \dfrac{1}{\sqrt2}$, both values $\dfrac{\pi}{4}$. (c) (i) Right of $K$ the rising curve is higher. (ii) Subtract heights.`,
  children: [
    child('a', mk.mcq({ stem: r`The range of the curve that starts at $(-1, \pi)$ is`, opts: [r`$[0, \pi]$`, r`$\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$`, r`$[-1, 1]$`, r`$(0, \pi)$`], key: 'a', sol: r`That curve is $y = \cos^{-1} x$, which takes every value from $0$ (at $x = 1$) to $\pi$ (at $x = -1$), both included.`, d: 1, c: 'recall', t: [2], time: 45 })),
    child('b', mk.num({ stem: r`Find the $y$-coordinate of $K$ in degrees.`, value: 45, unit: 'degrees', sol: r`At $x = \dfrac{1}{\sqrt2}$, $\sin^{-1} x = \cos^{-1} x = \dfrac{\pi}{4}$, so $K = \left(\dfrac{1}{\sqrt2}, \dfrac{\pi}{4}\right)$ and the height in degrees is $\dfrac{180}{4} = 45$.`, scheme: [['45', 1]], d: 2, c: 'understanding', t: [1, 2], time: 75 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** Use the graph to find all $x$ for which $\sin^{-1} x > \cos^{-1} x$.`, model: r`The curves cross only at $K$, where $x = \dfrac{1}{\sqrt2}$. To the right of $K$ the rising curve $y = \sin^{-1} x$ is above the falling curve $y = \cos^{-1} x$ (for example at $x = 1$: $\dfrac{\pi}{2} > 0$). So $\sin^{-1} x > \cos^{-1} x$ for $\dfrac{1}{\sqrt2} < x \le 1$.`, sol: 'Which curve is on top, and where.', scheme: [['Crossing at $x = \\dfrac{1}{\\sqrt2}$', 1], ['$\\dfrac{1}{\\sqrt2} < x \\le 1$', 1]], d: 3, c: 'application', t: [2], time: 150 }), [
      mk.short({ marks: 2, stem: r`**(ii)** Find the vertical gap between the two curves at $x = 0$ and at $x = -1$.`, model: r`At $x = 0$: $\cos^{-1} 0 - \sin^{-1} 0 = \dfrac{\pi}{2} - 0 = \dfrac{\pi}{2}$. At $x = -1$: $\cos^{-1}(-1) - \sin^{-1}(-1) = \pi - \left(-\dfrac{\pi}{2}\right) = \dfrac{3\pi}{2}$.`, sol: 'Difference of the two heights.', scheme: [['Gap $\\dfrac{\\pi}{2}$ at $x = 0$', 1], ['Gap $\\dfrac{3\\pi}{2}$ at $x = -1$', 1]], d: 2, c: 'understanding', t: [1, 2], time: 120 }),
    ]),
  ],
}, (C) => { C.child('a').which([[0, P], [-P / 2, P / 2], [-1, 1], [0.001, P - 0.001]], [Math.acos(1), Math.acos(-1)]); let lo = 0, hi = 1; for (let i = 0; i < 80; i++) { const m = (lo + hi) / 2; if (Math.asin(m) < Math.acos(m)) lo = m; else hi = m; } C.child('b').val(deg(Math.asin(lo)), 1e-6); C.child('c').assert(Math.abs(lo - Math.SQRT1_2) < 1e-9 && Math.asin(0.8) > Math.acos(0.8) && Math.asin(0.6) < Math.acos(0.6), 'crossing 1/√2'); C.child('c').model([r`\dfrac{1}{\sqrt2} < x \le 1`]); C.child('cii').model([piTex(Math.acos(0) - Math.asin(0)), piTex(Math.acos(-1) - Math.asin(-1))]); });
caseQ('c05', {
  passage: r`A giant wheel at a fair in Pune has radius $8$ m. The height of a seat above the level of the wheel's centre is $h = 8\sin\theta$ metres, where $\theta$ is the angle turned from the horizontal radius on the right. A student uses inverse sine to find $\theta$ from a measured height.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $\dfrac{\pi}{6}$. (b) $-30$. (c) (i) $\dfrac{5\pi}{6}$; $\sin^{-1}$ only returns angles in $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$. Or (ii) $-\dfrac{\pi}{2}$ and $\dfrac{\pi}{3}$.`,
  sol: r`(a) $\sin^{-1}\dfrac48$. (b) $\sin^{-1}\left(-\dfrac12\right)$. (c) (i) Second angle with the same sine. (ii) $\sin^{-1}(-1)$ and $\sin^{-1}\dfrac{\sqrt3}{2}$.`,
  children: [
    child('a', mk.mcq({ stem: r`A seat is $4$ m above the centre. The principal value $\theta = \sin^{-1}\dfrac{h}{8}$ is`, opts: [r`$\dfrac{\pi}{6}$`, r`$\dfrac{\pi}{3}$`, r`$\dfrac{5\pi}{6}$`, r`$\dfrac{\pi}{4}$`], key: 'a', sol: r`$\sin^{-1}\dfrac{4}{8} = \sin^{-1}\dfrac12 = \dfrac{\pi}{6}$. Option (c) has the same sine but is outside the principal range.`, d: 2, c: 'understanding', t: [1], time: 60 })),
    child('b', mk.num({ stem: r`A seat is $4$ m **below** the centre. Find the principal value $\sin^{-1}\dfrac{h}{8}$ in degrees.`, value: -30, unit: 'degrees', sol: r`$h = -4$: $\sin^{-1}\left(-\dfrac12\right) = -\dfrac{\pi}{6}$; in degrees $-\dfrac{180}{6} = -30$.`, scheme: [['−30', 1]], d: 2, c: 'understanding', t: [1], time: 60 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** In one full turn a seat is $4$ m above the centre twice. Find the other angle in $[0, 2\pi)$ and explain why $\sin^{-1}$ gives only one of the two.`, model: r`$\sin\theta = \dfrac12$ in $[0, 2\pi)$ at $\theta = \dfrac{\pi}{6}$ and $\theta = \pi - \dfrac{\pi}{6} = \dfrac{5\pi}{6}$. The other angle is $\dfrac{5\pi}{6}$. $\sin^{-1}$ is a function, so it must give one output; it returns the value in its principal range $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$, and $\dfrac{5\pi}{6}$ is outside it.`, sol: 'Two angles share the sine; the branch picks one.', scheme: [['Other angle $\\dfrac{5\\pi}{6}$', 1], ['Reason: principal range', 1]], d: 3, c: 'analysis', t: [1], time: 150 }), [
      mk.short({ marks: 2, stem: r`**(ii)** Find the principal values $\sin^{-1}\dfrac{h}{8}$ for a seat at the lowest point of the wheel and for a seat $4\sqrt3$ m above the centre.`, model: r`Lowest point: $h = -8$, $\sin^{-1}(-1) = -\dfrac{\pi}{2}$. For $h = 4\sqrt3$: $\sin^{-1}\dfrac{4\sqrt3}{8} = \sin^{-1}\dfrac{\sqrt3}{2} = \dfrac{\pi}{3}$.`, sol: 'Divide by the radius first.', scheme: [['$-\\dfrac{\\pi}{2}$', 1], ['$\\dfrac{\\pi}{3}$', 1]], d: 2, c: 'understanding', t: [1], time: 120 }),
    ]),
  ],
}, (C) => { const th = (h) => Math.asin(h / 8); C.child('a').which([P / 6, P / 3, 5 * P / 6, P / 4], th(4)); C.child('b').val(deg(th(-4))); const other = P - th(4); C.child('c').assert(near(Math.sin(other), 0.5) && other > P / 2, 'second angle'); C.child('c').model([piTex(other)]); C.child('cii').model([piTex(th(-8)), piTex(th(4 * S3))]); });
